cypress_script:
describe('Mobile-Viewport Product Browsing via Burger Menu', () => {
  it('should open the burger menu and display all items', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="open-menu"]').click();
    cy.get('[data-test="inventory-sidebar-link"]').should('be.visible');
    cy.get('[data-test="about-sidebar-link"]').should('be.visible');
    cy.get('[data-test="logout-sidebar-link"]').should('be.visible');
    cy.get('[data-test="reset-sidebar-link"]').should('be.visible');
  });

  it('should not navigate to a new page when clicking the close button', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="open-menu"]').click();
    cy.get('[data-test="close-menu"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/inventory.html');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Mobile-Viewport Product Browsing via Burger Menu', () => {
  test('should open the burger menu and display all items', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.click('[data-test="open-menu"]');
    await expect(page.locator('[data-test="inventory-sidebar-link"]')).toBeVisible();
    await expect(page.locator('[data-test="about-sidebar-link"]')).toBeVisible();
    await expect(page.locator('[data-test="logout-sidebar-link"]')).toBeVisible();
    await expect(page.locator('[data-test="reset-sidebar-link"]')).toBeVisible();
  });

  test('should not navigate to a new page when clicking the close button', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.click('[data-test="open-menu"]');
    await page.click('[data-test="close-menu"]');
    await expect(page).toHaveURL('https://www.saucedemo.com/inventory.html');
  });
});
